388|unsigned long long ZSTD_findDecompressedSize(const void* src, size_t srcSize)
389|{
390|    unsigned long long totalDstSize = 0;
391|
392|    while (srcSize >= ZSTD_frameHeaderSize_prefix) {
393|        const U32 magicNumber = MEM_readLE32(src);
394|
395|        if ((magicNumber & 0xFFFFFFF0U) == ZSTD_MAGIC_SKIPPABLE_START) {
396|            size_t skippableSize;
397|            if (srcSize < ZSTD_skippableHeaderSize)
398|                return ERROR(srcSize_wrong);
399|            skippableSize = MEM_readLE32((const BYTE *)src + 4) +
400|                            ZSTD_skippableHeaderSize;
401|            if (srcSize < skippableSize) {
402|                return ZSTD_CONTENTSIZE_ERROR;
403|            }
404|
405|            src = (const BYTE *)src + skippableSize;
406|            srcSize -= skippableSize;
407|            continue;
408|        }
409|
410|        {   unsigned long long const ret = ZSTD_getFrameContentSize(src, srcSize);
411|            if (ret >= ZSTD_CONTENTSIZE_ERROR) return ret;
412|
413|            /* check for overflow */
414|            if (totalDstSize + ret < totalDstSize) return ZSTD_CONTENTSIZE_ERROR;
415|            totalDstSize += ret;
416|        }
417|        {   size_t const frameSrcSize = ZSTD_findFrameCompressedSize(src, srcSize);
418|            if (ZSTD_isError(frameSrcSize)) {
419|                return ZSTD_CONTENTSIZE_ERROR;
420|            }
421|
422|            src = (const BYTE *)src + frameSrcSize;
423|            srcSize -= frameSrcSize;
424|        }
425|    }
426|
427|    if (srcSize) {
428|        return ZSTD_CONTENTSIZE_ERROR;
429|    }
430|
431|    return totalDstSize;
432|}

