747|    /* check */
748|    if (srcSize < MIN_SEQUENCES_SIZE) return ERROR(srcSize_wrong);
749|
750|    /* SeqHead */
751|    {   int nbSeq = *ip++;
752|        if (!nbSeq) { *nbSeqPtr=0; return 1; }
753|        if (nbSeq > 0x7F) {
754|            if (nbSeq == 0xFF) {
755|                if (ip+2 > iend) return ERROR(srcSize_wrong);
756|                nbSeq = MEM_readLE16(ip) + LONGNBSEQ, ip+=2;
757|            } else {
758|                if (ip >= iend) return ERROR(srcSize_wrong);
759|                nbSeq = ((nbSeq-0x80)<<8) + *ip++;
