767|    {   symbolEncodingType_e const LLtype = (symbolEncodingType_e)(*ip >> 6);
768|        symbolEncodingType_e const OFtype = (symbolEncodingType_e)((*ip >> 4) & 3);
769|        symbolEncodingType_e const MLtype = (symbolEncodingType_e)((*ip >> 2) & 3);
770|        ip++;
771|
772|        /* Build DTables */
773|        {   size_t const llhSize = ZSTD_buildSeqTable(dctx->entropy.LLTable, &dctx->LLTptr,
774|                                                      LLtype, MaxLL, LLFSELog,
775|                                                      ip, iend-ip, LL_defaultDTable, dctx->fseEntropy);
776|            if (ZSTD_isError(llhSize)) return ERROR(corruption_detected);
777|            ip += llhSize;
778|        }
779|        {   size_t const ofhSize = ZSTD_buildSeqTable(dctx->entropy.OFTable, &dctx->OFTptr,
780|                                                      OFtype, MaxOff, OffFSELog,
781|                                                      ip, iend-ip, OF_defaultDTable, dctx->fseEntropy);
782|            if (ZSTD_isError(ofhSize)) return ERROR(corruption_detected);
783|            ip += ofhSize;
784|        }
785|        {   size_t const mlhSize = ZSTD_buildSeqTable(dctx->entropy.MLTable, &dctx->MLTptr,
786|                                                      MLtype, MaxML, MLFSELog,
787|                                                      ip, iend-ip, ML_defaultDTable, dctx->fseEntropy);
788|            if (ZSTD_isError(mlhSize)) return ERROR(corruption_detected);
789|            ip += mlhSize;
790|        }
