1511|static size_t ZSTD_decompressFrame(ZSTD_DCtx* dctx,
1512|                                   void* dst, size_t dstCapacity,
1513|                             const void** srcPtr, size_t *srcSizePtr)
1514|{
1515|    const BYTE* ip = (const BYTE*)(*srcPtr);
1516|    BYTE* const ostart = (BYTE* const)dst;
1517|    BYTE* const oend = ostart + dstCapacity;
1518|    BYTE* op = ostart;
1519|    size_t remainingSize = *srcSizePtr;
1520|
1521|    /* check */
1522|    if (remainingSize < ZSTD_frameHeaderSize_min+ZSTD_blockHeaderSize)
1523|        return ERROR(srcSize_wrong);
1524|
1525|    /* Frame Header */
1526|    {   size_t const frameHeaderSize = ZSTD_frameHeaderSize(ip, ZSTD_frameHeaderSize_prefix);
1527|        if (ZSTD_isError(frameHeaderSize)) return frameHeaderSize;
1528|        if (remainingSize < frameHeaderSize+ZSTD_blockHeaderSize)
1529|            return ERROR(srcSize_wrong);
1530|        CHECK_F( ZSTD_decodeFrameHeader(dctx, ip, frameHeaderSize) );
1531|        ip += frameHeaderSize; remainingSize -= frameHeaderSize;
1532|    }
1533|
1534|    /* Loop on each block */
1535|    while (1) {
1536|        size_t decodedSize;
1537|        blockProperties_t blockProperties;
1538|        size_t const cBlockSize = ZSTD_getcBlockSize(ip, remainingSize, &blockProperties);
1539|        if (ZSTD_isError(cBlockSize)) return cBlockSize;
1540|
1541|        ip += ZSTD_blockHeaderSize;
1542|        remainingSize -= ZSTD_blockHeaderSize;
1543|        if (cBlockSize > remainingSize) return ERROR(srcSize_wrong);
1544|
1545|        switch(blockProperties.blockType)
1546|        {
1547|        case bt_compressed:
1548|            decodedSize = ZSTD_decompressBlock_internal(dctx, op, oend-op, ip, cBlockSize, /* frame */ 1);
1549|            break;
1550|        case bt_raw :
1551|            decodedSize = ZSTD_copyRawBlock(op, oend-op, ip, cBlockSize);
1552|            break;
1553|        case bt_rle :
1554|            decodedSize = ZSTD_generateNxBytes(op, oend-op, *ip, blockProperties.origSize);
1555|            break;
1556|        case bt_reserved :
1557|        default:
1558|            return ERROR(corruption_detected);
1559|        }
1560|
1561|        if (ZSTD_isError(decodedSize)) return decodedSize;
1562|        if (dctx->fParams.checksumFlag)
1563|            XXH64_update(&dctx->xxhState, op, decodedSize);
1564|        op += decodedSize;
1565|        ip += cBlockSize;
1566|        remainingSize -= cBlockSize;
1567|        if (blockProperties.lastBlock) break;
1568|    }
1569|
1570|    if (dctx->fParams.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN) {
1571|        if ((U64)(op-ostart) != dctx->fParams.frameContentSize) {
1572|            return ERROR(corruption_detected);
1573|    }   }
