1575|        U32 const checkCalc = (U32)XXH64_digest(&dctx->xxhState);
1576|        U32 checkRead;
1577|        if (remainingSize<4) return ERROR(checksum_wrong);
1578|        checkRead = MEM_readLE32(ip);
1579|        if (checkRead != checkCalc) return ERROR(checksum_wrong);
1580|        ip += 4;
1581|        remainingSize -= 4;
1582|    }
